CREATE TYPE "Role" AS ENUM ('ADMIN','EDITOR');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'EDITOR',"refreshTokenHash" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Page" ("id" TEXT PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"title" TEXT NOT NULL,"published" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Block" ("id" TEXT PRIMARY KEY,"pageId" TEXT NOT NULL,"type" TEXT NOT NULL,"position" INTEGER NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"data" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Block_pageId_fkey" FOREIGN KEY ("pageId") REFERENCES "Page"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "Block_pageId_position_key" ON "Block"("pageId","position"); CREATE INDEX "Block_pageId_idx" ON "Block"("pageId");
